const int PIN_R = 18; // AP9962GH (Directo)
const int PIN_G = 19; // AP9962GH (Directo)
const int PIN_B = 20; // AP2761I  (Invertido por NPN)

void setup() {
  pinMode(PIN_R, OUTPUT);
  pinMode(PIN_G, OUTPUT);
  pinMode(PIN_B, OUTPUT);

  analogWriteFreq(2000); // Frecuencia PWM de 2 kHz
  analogWriteRange(255); // Rango estándar 0-255

  setRGB(0, 0, 0); // Arrancar apagado
}

void setRGB(uint8_t r, uint8_t g, uint8_t b) {
  analogWrite(PIN_R, r);
  analogWrite(PIN_G, g);
  // Canal Azul invertido por el driver NPN: 255 = apagado, 0 = encendido al 100%
  analogWrite(PIN_B, 255 - b); 
}

void loop() {
  // 1. Prueba individual de canales primarios (2 seg cada uno)
  setRGB(255, 0, 0);   // ROJO puro
  delay(2000);

  setRGB(0, 255, 0);   // VERDE puro
  delay(2000);

  setRGB(0, 0, 255);   // AZUL puro
  delay(2000);

  // 2. Prueba de mezcla de colores (1.5 seg cada uno)
  setRGB(255, 255, 0); // AMARILLO (Rojo + Verde)
  delay(1500);

  setRGB(0, 255, 255); // CIAN (Verde + Azul)
  delay(1500);

  setRGB(255, 0, 255); // MAGENTA (Rojo + Azul)
  delay(1500);

  // 3. Prueba de atenuación PWM (Respiración en Blanco)
  for (int brillo = 0; brillo <= 255; brillo++) {
    setRGB(brillo, brillo, brillo);
    delay(8); // Sube suavemente en ~2 segundos
  }
  delay(1500); // Mantiene blanco al 100% (máxima carga)
  for (int brillo = 255; brillo >= 0; brillo--) {
    setRGB(brillo, brillo, brillo);
    delay(8); // Baja suavemente hasta apagar
  }

  delay(1000); // Pausa totalmente apagado
}
